import sys

def solve(s):
    T = '#'.join(f'^{s}$')
    n = len(T); P = [0] * n; C = R = 0
    for i in range(1, n-1):
        mirror = 2 * C - i
        if i < R: P[i] = min(R - i, P[mirror])
        while T[i + P[i] + 1] == T[i - P[i] - 1]: P[i] += 1
        if i + P[i] > R: C, R = i, i + P[i]
    return str(max(P))

if __name__ == '__main__':
    s = sys.stdin.read().strip()
    print(solve(s))

